CREATE TABLE public.b2b_pricing_versions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, status text NOT NULL DEFAULT 'draft', enabled boolean NOT NULL DEFAULT true, effective_from timestamptz NOT NULL DEFAULT now(), effective_until timestamptz, service_gst_bps integer NOT NULL DEFAULT 1800, created_by uuid, approved_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.b2b_pricing_versions TO authenticated; GRANT ALL ON public.b2b_pricing_versions TO service_role;
ALTER TABLE public.b2b_pricing_versions ENABLE ROW LEVEL SECURITY;
CREATE POLICY b2b_versions_admin ON public.b2b_pricing_versions FOR ALL TO authenticated USING(public.is_super_admin(auth.uid())) WITH CHECK(public.is_super_admin(auth.uid()));
CREATE TABLE public.b2b_pricing_tiers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), version_id uuid NOT NULL REFERENCES public.b2b_pricing_versions(id), tier integer NOT NULL, name text NOT NULL, min_shipments integer NOT NULL, max_shipments integer, booking_fee_paise bigint, enabled boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(version_id,tier));
GRANT SELECT,INSERT,UPDATE ON public.b2b_pricing_tiers TO authenticated; GRANT ALL ON public.b2b_pricing_tiers TO service_role;
ALTER TABLE public.b2b_pricing_tiers ENABLE ROW LEVEL SECURITY;
CREATE POLICY b2b_tiers_admin ON public.b2b_pricing_tiers FOR ALL TO authenticated USING(public.is_super_admin(auth.uid())) WITH CHECK(public.is_super_admin(auth.uid()));
CREATE TABLE public.b2b_pricing_slabs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tier_id uuid NOT NULL REFERENCES public.b2b_pricing_tiers(id), upper_weight_g integer NOT NULL, fee_per_500g_paise bigint NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tier_id,upper_weight_g));
GRANT SELECT,INSERT,UPDATE ON public.b2b_pricing_slabs TO authenticated; GRANT ALL ON public.b2b_pricing_slabs TO service_role;
ALTER TABLE public.b2b_pricing_slabs ENABLE ROW LEVEL SECURITY;
CREATE POLICY b2b_slabs_admin ON public.b2b_pricing_slabs FOR ALL TO authenticated USING(public.is_super_admin(auth.uid())) WITH CHECK(public.is_super_admin(auth.uid()));
CREATE TABLE public.b2b_customer_rate_cards (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_account_id uuid NOT NULL REFERENCES public.business_accounts(id), name text NOT NULL, kind text NOT NULL DEFAULT 'customer', status text NOT NULL DEFAULT 'draft', enabled boolean NOT NULL DEFAULT true, booking_fee_paise bigint NOT NULL, slabs jsonb NOT NULL, effective_from timestamptz NOT NULL, effective_until timestamptz, approved_by uuid, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.b2b_customer_rate_cards TO authenticated; GRANT ALL ON public.b2b_customer_rate_cards TO service_role;
ALTER TABLE public.b2b_customer_rate_cards ENABLE ROW LEVEL SECURITY;
CREATE POLICY b2b_cards_admin ON public.b2b_customer_rate_cards FOR ALL TO authenticated USING(public.is_super_admin(auth.uid())) WITH CHECK(public.is_super_admin(auth.uid()));
CREATE TABLE public.b2b_tier_overrides (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_account_id uuid NOT NULL REFERENCES public.business_accounts(id), tier integer NOT NULL, effective_from timestamptz NOT NULL, effective_until timestamptz, reason text NOT NULL, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.b2b_tier_overrides TO authenticated; GRANT ALL ON public.b2b_tier_overrides TO service_role;
ALTER TABLE public.b2b_tier_overrides ENABLE ROW LEVEL SECURITY;
CREATE POLICY b2b_overrides_admin ON public.b2b_tier_overrides FOR ALL TO authenticated USING(public.is_super_admin(auth.uid())) WITH CHECK(public.is_super_admin(auth.uid()));
CREATE TABLE public.b2b_monthly_tiers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_account_id uuid NOT NULL REFERENCES public.business_accounts(id), month date NOT NULL, completed_shipments integer NOT NULL, tier integer NOT NULL, version_id uuid NOT NULL REFERENCES public.b2b_pricing_versions(id), missing_completion_evidence integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(business_account_id,month));
GRANT SELECT ON public.b2b_monthly_tiers TO authenticated; GRANT ALL ON public.b2b_monthly_tiers TO service_role;
ALTER TABLE public.b2b_monthly_tiers ENABLE ROW LEVEL SECURITY;
CREATE POLICY b2b_month_admin ON public.b2b_monthly_tiers FOR SELECT TO authenticated USING(public.is_super_admin(auth.uid()));
CREATE TABLE public.b2b_courier_pricing_rules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), partner_code text NOT NULL, service_code text NOT NULL DEFAULT '*', volumetric_divisor integer NOT NULL, minimum_weight_g integer NOT NULL, billing_increment_g integer NOT NULL, package_rule text NOT NULL DEFAULT 'sum_billed', freight_tax_treatment text NOT NULL, freight_gst_bps integer NOT NULL DEFAULT 1800, enabled boolean NOT NULL DEFAULT true, effective_from timestamptz NOT NULL DEFAULT now(), effective_until timestamptz, evidence text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.b2b_courier_pricing_rules TO authenticated; GRANT ALL ON public.b2b_courier_pricing_rules TO service_role;
ALTER TABLE public.b2b_courier_pricing_rules ENABLE ROW LEVEL SECURITY;
CREATE POLICY b2b_courier_rules_admin ON public.b2b_courier_pricing_rules FOR ALL TO authenticated USING(public.is_super_admin(auth.uid())) WITH CHECK(public.is_super_admin(auth.uid()));
CREATE TABLE public.b2b_quotes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_account_id uuid NOT NULL REFERENCES public.business_accounts(id), version_id uuid NOT NULL REFERENCES public.b2b_pricing_versions(id), environment text NOT NULL, request_fingerprint text NOT NULL, request jsonb NOT NULL, snapshot jsonb NOT NULL, expires_at timestamptz NOT NULL, booking_id uuid UNIQUE REFERENCES public.bookings(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.b2b_quotes TO authenticated; GRANT ALL ON public.b2b_quotes TO service_role;
ALTER TABLE public.b2b_quotes ENABLE ROW LEVEL SECURITY;
CREATE POLICY b2b_quotes_admin ON public.b2b_quotes FOR SELECT TO authenticated USING(public.is_super_admin(auth.uid()));
CREATE TABLE public.b2b_booking_pricing_snapshots (booking_id uuid PRIMARY KEY REFERENCES public.bookings(id), quote_id uuid NOT NULL UNIQUE REFERENCES public.b2b_quotes(id), business_account_id uuid NOT NULL REFERENCES public.business_accounts(id), snapshot jsonb NOT NULL, box_allocations jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.b2b_booking_pricing_snapshots TO authenticated; GRANT ALL ON public.b2b_booking_pricing_snapshots TO service_role;
ALTER TABLE public.b2b_booking_pricing_snapshots ENABLE ROW LEVEL SECURITY;
CREATE POLICY b2b_snapshots_admin ON public.b2b_booking_pricing_snapshots FOR SELECT TO authenticated USING(public.is_admin(auth.uid()));
CREATE TABLE public.b2b_pricing_audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_user_id uuid, resource_type text NOT NULL, resource_id text NOT NULL, action text NOT NULL, before_value jsonb, after_value jsonb, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.b2b_pricing_audit_logs TO authenticated; GRANT ALL ON public.b2b_pricing_audit_logs TO service_role;
ALTER TABLE public.b2b_pricing_audit_logs ENABLE ROW LEVEL SECURITY;
CREATE POLICY b2b_audit_admin ON public.b2b_pricing_audit_logs FOR SELECT TO authenticated USING(public.is_super_admin(auth.uid()));
ALTER TABLE public.bookings ADD COLUMN b2b_quote_id uuid REFERENCES public.b2b_quotes(id);
CREATE OR REPLACE FUNCTION public.b2b_pricing_audit() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.b2b_pricing_audit_logs(actor_user_id,resource_type,resource_id,action,before_value,after_value) VALUES(auth.uid(),TG_TABLE_NAME,NEW.id::text,lower(TG_OP),CASE WHEN TG_OP='UPDATE' THEN to_jsonb(OLD) ELSE NULL END,to_jsonb(NEW)); RETURN NEW; END; $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['b2b_pricing_versions','b2b_pricing_tiers','b2b_pricing_slabs','b2b_customer_rate_cards','b2b_tier_overrides','b2b_courier_pricing_rules'] LOOP EXECUTE format('CREATE TRIGGER b2b_audit AFTER INSERT OR UPDATE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.b2b_pricing_audit()',t); EXECUTE format('CREATE TRIGGER b2b_updated BEFORE UPDATE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column()',t); END LOOP; END $$;
CREATE OR REPLACE FUNCTION public.b2b_resolve_month(_business_id uuid, _version_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE m date:=date_trunc('month',now() AT TIME ZONE 'Asia/Kolkata')::date; n integer; missing integer; r public.b2b_monthly_tiers; chosen integer; current_n integer; BEGIN SELECT * INTO r FROM public.b2b_monthly_tiers WHERE business_account_id=_business_id AND month=m; IF NOT FOUND THEN SELECT count(*) INTO n FROM (SELECT b.id,min(e.event_time) AS delivered_at FROM public.bookings b JOIN public.shipment_status_events e ON e.booking_id=b.id AND upper(e.normalized_status)='DELIVERED' WHERE b.business_account_id=_business_id AND upper(coalesce(b.status,''))='DELIVERED' GROUP BY b.id) d WHERE delivered_at >= ((m-interval '1 month') AT TIME ZONE 'Asia/Kolkata') AND delivered_at < (m AT TIME ZONE 'Asia/Kolkata'); SELECT count(*) INTO missing FROM public.bookings b WHERE b.business_account_id=_business_id AND upper(coalesce(b.status,''))='DELIVERED' AND NOT EXISTS(SELECT 1 FROM public.shipment_status_events e WHERE e.booking_id=b.id AND upper(e.normalized_status)='DELIVERED'); SELECT tier INTO chosen FROM public.b2b_pricing_tiers WHERE version_id=_version_id AND min_shipments<=n AND (max_shipments IS NULL OR max_shipments>=n) ORDER BY min_shipments DESC LIMIT 1; IF chosen IS NULL THEN RAISE EXCEPTION 'No tier configured for completed volume'; END IF; INSERT INTO public.b2b_monthly_tiers(business_account_id,month,completed_shipments,tier,version_id,missing_completion_evidence) VALUES(_business_id,m,n,chosen,_version_id,missing) ON CONFLICT(business_account_id,month) DO NOTHING; SELECT * INTO r FROM public.b2b_monthly_tiers WHERE business_account_id=_business_id AND month=m; END IF; SELECT count(*) INTO current_n FROM (SELECT b.id,min(e.event_time) delivered_at FROM public.bookings b JOIN public.shipment_status_events e ON e.booking_id=b.id AND upper(e.normalized_status)='DELIVERED' WHERE b.business_account_id=_business_id AND upper(coalesce(b.status,''))='DELIVERED' GROUP BY b.id) d WHERE delivered_at >= (m AT TIME ZONE 'Asia/Kolkata') AND delivered_at < ((m+interval '1 month') AT TIME ZONE 'Asia/Kolkata'); RETURN to_jsonb(r)||jsonb_build_object('current_completed',current_n); END $$;
REVOKE ALL ON FUNCTION public.b2b_resolve_month(uuid,uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.b2b_resolve_month(uuid,uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.b2b_bind_quote() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE q public.b2b_quotes; s jsonb; BEGIN IF NEW.b2b_quote_id IS NULL THEN RETURN NEW; END IF; SELECT * INTO q FROM public.b2b_quotes WHERE id=NEW.b2b_quote_id FOR UPDATE; IF NOT FOUND OR q.business_account_id IS DISTINCT FROM NEW.business_account_id OR q.booking_id IS NOT NULL OR q.expires_at<=now() THEN RAISE EXCEPTION 'Invalid, expired or already used business quote'; END IF; IF NEW.account_type<>'business' THEN RAISE EXCEPTION 'Business quote requires business booking'; END IF; s:=q.snapshot; NEW.courier_price:=(s->>'total_paise')::numeric/100; NEW.courier_rate:=(s->>'freight_net_paise')::numeric/100; NEW.base_fare:=(s->>'net_paise')::numeric/100; NEW.gst:=(s->>'gst_paise')::numeric/100; NEW.platform_fee:=(s->>'platform_fee_paise')::numeric/100; NEW.margin_amount:=NEW.platform_fee; NEW.partner_id:=s->>'partner_id'; NEW.service_code:=s->>'service_code'; NEW.courier_name:=(s->>'partner_name')||' - '||(s->>'service_name'); RETURN NEW; END $$;
CREATE TRIGGER b2b_bind_quote BEFORE INSERT ON public.bookings FOR EACH ROW EXECUTE FUNCTION public.b2b_bind_quote();
CREATE OR REPLACE FUNCTION public.b2b_save_snapshot() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.b2b_quote_id IS NOT NULL THEN UPDATE public.b2b_quotes SET booking_id=NEW.id WHERE id=NEW.b2b_quote_id; INSERT INTO public.b2b_booking_pricing_snapshots(booking_id,quote_id,business_account_id,snapshot,box_allocations) SELECT NEW.id,id,business_account_id,snapshot,snapshot->'boxes' FROM public.b2b_quotes WHERE id=NEW.b2b_quote_id; END IF; RETURN NEW; END $$;
CREATE TRIGGER b2b_save_snapshot AFTER INSERT ON public.bookings FOR EACH ROW EXECUTE FUNCTION public.b2b_save_snapshot();
CREATE OR REPLACE FUNCTION public.b2b_protect_snapshot() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN RAISE EXCEPTION 'Historical pricing snapshots are immutable'; END $$;
CREATE TRIGGER b2b_immutable BEFORE UPDATE OR DELETE ON public.b2b_booking_pricing_snapshots FOR EACH ROW EXECUTE FUNCTION public.b2b_protect_snapshot();
DO $$ DECLARE v uuid; t uuid; i integer; j integer; fees integer[][]:=ARRAY[[2000,1500,1000,625,375],[1700,1250,875,500,300],[1400,1000,750,425,250]]; limits integer[]:=ARRAY[500,2000,5000,10000,25000]; BEGIN INSERT INTO public.b2b_pricing_versions(name,status,effective_from) VALUES('Approved progressive B2B pricing','published',now()) RETURNING id INTO v; FOR i IN 1..4 LOOP INSERT INTO public.b2b_pricing_tiers(version_id,tier,name,min_shipments,max_shipments,booking_fee_paise) VALUES(v,i,(ARRAY['Starter','Growth','Business','Enterprise'])[i],(ARRAY[0,50,201,1001])[i],(ARRAY[49,200,1000,NULL])[i],(ARRAY[1000,800,600,NULL])[i]) RETURNING id INTO t; IF i<=3 THEN FOR j IN 1..5 LOOP INSERT INTO public.b2b_pricing_slabs(tier_id,upper_weight_g,fee_per_500g_paise) VALUES(t,limits[j],fees[i][j]); END LOOP; END IF; END LOOP; END $$;
INSERT INTO public.b2b_courier_pricing_rules(partner_code,volumetric_divisor,minimum_weight_g,billing_increment_g,freight_tax_treatment,evidence) VALUES('delhivery',5000,500,500,'exclusive','Existing serviceability normalizes gross_amount; gst_included_in_rate=false. Uses max(actual,volumetric/5000).'),('shree_maruti',5000,500,500,'exclusive','Shared Excel-derived rate card explicitly pre-tax; courier chargeable_g metadata retained.'),('xpressbees',5000,500,250,'exclusive','Existing xpressbees-rates excludes GST; service chargeable_weight_kg and slab_weight_g take precedence over minimum billing increment.'),('shadowfax',5000,500,500,'exclusive','Marketplace 360 Standard card pre-tax, 30% FSC; divisor 5000 and 500g increments.'),('urbanebolt',5000,500,500,'exclusive','Embedded rate card pre-tax; chargeable_g metadata retained.');